        rs={r for r,_ in cs}; cc={c for _,c in cs}
        if len(rs)==len(cc)==1:  # vertical/horizontal line
            pass
        if len(rs)==len(cc):   # diagonal or single cell - handle
            r0=rs|{rs.pop() if False else None}
