        if v<2: continue
        pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==k]
        rowsmap={}
        for r,c in pts: rowsmap.setdefault(r,set()).add(c)
        colsmap={}
        for r,c in pts: colsmap.setdefault(c,set()).add(r)
        for r,s in rowsmap.items():
            if len(s)==len(pts):  # horizontal line
                for c in sorted(s,key=lambda c:c<(W-len(s))) : pass
        # simpler: vertical lines
        for c,s in colsmap.items():
