def f(g):
    H,W=len(g),len(g[0]); bg=g[0][0]
    out=[r[:] for r in g]
    from collections import deque
    seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                v=g[i][j]; q=deque([(i,j)]); comp={(i,j)}; seen.add((i,j))
                while q:
                    x,y=q.popleft()
                    for dx,dy in [(-1,-1),(1,1)]:
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]==v and (nx,ny) not in seen:
                            seen.add((nx,ny)); comp.add((nx,ny)); q.append((nx,ny))
                comps.append((v,comp))
    for v,comp in comps:
        if len(comp)<2: continue
        d0=min(p[0]-p[1] for p in comp)
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        def room(dirn):
            # cells from outermost tip along dirn until blocked
            cnt=0; x,y=min(comp,key=lambda p:(p[0] if dirn==1 else max(p[0])))
            if dirn==-1: x,y=max(comp,key=lambda p:max(p[0]),key=lambda p:p[0])([p for p in comp if p[0]==min(rs)])[0]
            tt=min([p for p in comp if p[0]==min(rs)][0], key=lambda p:p[0]) if dirn==-1 else min([p for p in comp if p[0]==max(rs)][0], key=lambda p:p[0])
            while True:
                nx,ny=x+(dirn* -1)+ (tt[0]-tt[1]) , y
                break
            return 0
        # simply: try both diagonal directions from each end cell; count reachable bg cells before foreign
        res={}
        for s in [(min(rs),min(cs)),(max(rs),max(cs))]:
            for dx,dy in [(-1,-1),(1,1)]:
                cnt=0; x,y=s
                while 0<=x<H and 0<=y<W and out[x][y]==bg:
                    out[x][y]=v; x+=dx; y+=dy; cnt+=1
            res.setdefault(dx,[]).append(res.get((-dx,dy),[])[0] if False else None)
    return out
